perl -e '
open(F, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die $!;
seek(F, 1048576, 0);
read(F, my $hdr, 100);

# Parse local file header
my @bytes = unpack("C*", $hdr);
printf("Signature: %02X %02X %02X %02X\n", @bytes[0..3]);
my $version = unpack("v", substr($hdr, 4, 2));
my $flags = unpack("v", substr($hdr, 6, 2));
my $method = unpack("v", substr($hdr, 8, 2));
my $fname_len = unpack("v", substr($hdr, 26, 2));
my $extra_len = unpack("v", substr($hdr, 28, 2));
my $comp_size = unpack("V", substr($hdr, 18, 4));
my $uncomp_size = unpack("V", substr($hdr, 22, 4));

printf("Method: %d (0=store, 8=deflate)\n", $method);
printf("Flags: %04X (encrypted if bit 0 set: %d)\n", $flags, $flags & 1);
printf("Fname len: %d, Extra len: %d\n", $fname_len, $extra_len);
printf("Compressed size: %d, Uncompressed size: %d\n", $comp_size, $uncomp_size);
printf("Filename: %s\n", substr($hdr, 30, $fname_len));

my $data_offset = 30 + $fname_len + $extra_len;
printf("Data starts at local offset: %d (global: %d)\n", $data_offset, 1048576 + $data_offset);
'

