open(F, "<:raw", "/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat") or die $!;
seek(F, 1048652, 0);
read(F, my $data, 33);
close(F);

my $ctx = Digest::CRC->new(type => "crc32");
$ctx->add($data);
printf("CRC-32 of ZIP content: %08X\n", $ctx->digest);
printf("Expected CRC-32:       B0725DC4\n");
' 2>/dev/null || echo "Digest::CRC not available"

